{
  "name": "whatsapp-command-channel",
  "version": "1.0.0",
  "description": "Turn your own WhatsApp into a command center for Claude — text it, Claude does the work and texts back.",
  "license": "MIT",
  "type": "commonjs",
  "scripts": {
    "test": "node --check command-center.cjs && node --check wa-daemon.cjs && node --check wa-watch.cjs && node --check wa-watchdog.cjs && node --check wa-reply.cjs && echo ok",
    "watchdog": "node wa-watchdog.cjs",
    "command-center": "node command-center.cjs",
    "check": "for f in *.cjs; do node --check \"$f\"; done && echo ok"
  },
  "keywords": [
    "whatsapp",
    "claude",
    "command-center",
    "ai-agent",
    "claude-cli",
    "baileys",
    "self-hosted",
    "automation"
  ],
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "@whiskeysockets/baileys": "^7.0.0-rc.13",
    "pino": "^10.0.0",
    "qrcode": "^1.5.4",
    "qrcode-terminal": "^0.12.0"
  },
  "devDependencies": {}
}
